"use client"

import * as React from "react"
import { interpolate } from "flubber"
import { cn } from "@/lib/utils"

/**
 * Creates SVG line drawing parameters based on start and end proportions [0..1].
 */
export function getSvgStrokeDash(
  totalLength: number,
  start: number = 0,
  end: number = 1
): { strokeDasharray: string; strokeDashoffset: string } {
  const clampedStart = Math.max(0, Math.min(1, start))
  const clampedEnd = Math.max(0, Math.min(1, end))
  const visibleLength = Math.max(0, (clampedEnd - clampedStart) * totalLength)
  const offset = -clampedStart * totalLength

  return {
    strokeDasharray: `${visibleLength} ${totalLength * 2}`,
    strokeDashoffset: `${offset}`,
  }
}

/**
 * Computes position (x, y) and tangent angle (degrees) along an SVG path.
 */
export function getPointOnPath(
  pathElement: SVGPathElement,
  progress: number
): { x: number; y: number; angle: number } {
  const totalLength = pathElement.getTotalLength()
  const clampedProgress = Math.max(0, Math.min(1, progress))
  const currentLength = clampedProgress * totalLength
  const point = pathElement.getPointAtLength(currentLength)

  // Tangent calculation
  const delta = 1
  const p1 = pathElement.getPointAtLength(Math.max(0, currentLength - delta))
  const p2 = pathElement.getPointAtLength(Math.min(totalLength, currentLength + delta))
  const angle = (Math.atan2(p2.y - p1.y, p2.x - p1.x) * 180) / Math.PI

  return { x: point.x, y: point.y, angle }
}

// -----------------------------------------------------------------------------
// 1. AnimeSvgMorph Component
// -----------------------------------------------------------------------------

export interface AnimeSvgMorphProps extends React.SVGProps<SVGSVGElement> {
  /** Array of SVG path d strings to morph between. */
  paths: string[]
  /** Active path index. */
  currentIndex?: number
  /** Transition duration in seconds. */
  duration?: number
  /** Fill color. */
  fill?: string
  /** Stroke color. */
  stroke?: string
  /** Stroke width. */
  strokeWidth?: number
  /** ViewBox coordinates. */
  viewBox?: string
}

export function AnimeSvgMorph({
  paths,
  currentIndex = 0,
  duration = 0.8,
  fill = "#10b981",
  stroke = "none",
  strokeWidth = 0,
  viewBox = "0 0 100 100",
  className,
  ...props
}: AnimeSvgMorphProps) {
  const [currentPath, setCurrentPath] = React.useState(paths[currentIndex] || "")
  const interpolatorRef = React.useRef<((t: number) => string) | null>(null)
  const animFrameRef = React.useRef<number | null>(null)
  const prevIndexRef = React.useRef(currentIndex)

  React.useEffect(() => {
    if (prevIndexRef.current === currentIndex) return

    const fromPath = paths[prevIndexRef.current] || paths[0]
    const toPath = paths[currentIndex] || paths[0]
    prevIndexRef.current = currentIndex

    try {
      interpolatorRef.current = interpolate(fromPath, toPath, { maxSegmentLength: 2 })
    } catch {
      interpolatorRef.current = null
      const frame = requestAnimationFrame(() => setCurrentPath(toPath))
      return () => cancelAnimationFrame(frame)
    }

    const startTime = performance.now()
    const durMs = duration * 1000

    const step = (time: number) => {
      const elapsed = time - startTime
      const progress = Math.min(1, elapsed / durMs)
      // Ease in-out expo
      const ease =
        progress === 0
          ? 0
          : progress === 1
          ? 1
          : progress < 0.5
          ? Math.pow(2, 20 * progress - 10) / 2
          : (2 - Math.pow(2, -20 * progress + 10)) / 2

      if (interpolatorRef.current) {
        setCurrentPath(interpolatorRef.current(ease))
      }

      if (progress < 1) {
        animFrameRef.current = requestAnimationFrame(step)
      }
    }

    animFrameRef.current = requestAnimationFrame(step)

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current)
    }
  }, [currentIndex, paths, duration])

  return (
    <svg
      viewBox={viewBox}
      data-slot="anime-svg-morph"
      className={cn("w-full h-full overflow-visible", className)}
      {...props}
    >
      <path
        d={currentPath}
        fill={fill}
        stroke={stroke}
        strokeWidth={strokeWidth}
        className="transition-colors duration-300"
      />
    </svg>
  )
}

// -----------------------------------------------------------------------------
// 2. AnimeSvgDraw Component
// -----------------------------------------------------------------------------

export interface AnimeSvgDrawProps extends React.SVGProps<SVGSVGElement> {
  /** SVG path d string to draw. */
  path: string
  /** Range tuple [start, end] from 0 to 1 defining the visible segment. */
  draw?: [number, number]
  /** Path stroke color. */
  stroke?: string
  /** Stroke width. */
  strokeWidth?: number
  /** ViewBox. */
  viewBox?: string
}

export function AnimeSvgDraw({
  path,
  draw = [0, 1],
  stroke = "#10b981",
  strokeWidth = 2,
  viewBox = "0 0 100 100",
  className,
  ...props
}: AnimeSvgDrawProps) {
  const pathRef = React.useRef<SVGPathElement>(null)
  const [totalLength, setTotalLength] = React.useState(100)

  React.useEffect(() => {
    if (pathRef.current) {
      setTotalLength(pathRef.current.getTotalLength() || 100)
    }
  }, [path])

  const { strokeDasharray, strokeDashoffset } = getSvgStrokeDash(
    totalLength,
    draw[0],
    draw[1]
  )

  return (
    <svg
      viewBox={viewBox}
      data-slot="anime-svg-draw"
      className={cn("w-full h-full overflow-visible", className)}
      {...props}
    >
      <path
        ref={pathRef}
        d={path}
        fill="none"
        stroke={stroke}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{
          strokeDasharray,
          strokeDashoffset,
          transition: "stroke-dasharray 0.3s ease-out, stroke-dashoffset 0.3s ease-out",
        }}
      />
    </svg>
  )
}

// -----------------------------------------------------------------------------
// 3. AnimeSvgMotionPath Component
// -----------------------------------------------------------------------------

export interface AnimeSvgMotionPathProps extends React.SVGProps<SVGSVGElement> {
  /** Guide curve path d string. */
  path: string
  /** Progress along the path from 0 to 1. */
  progress?: number
  /** Color of guide line. */
  pathColor?: string
  /** Custom follower element or glowing rocket/bead. */
  children?: React.ReactNode
  /** ViewBox. */
  viewBox?: string
}

export function AnimeSvgMotionPath({
  path,
  progress = 0,
  pathColor = "rgba(255, 255, 255, 0.15)",
  viewBox = "0 0 400 200",
  children,
  className,
  ...props
}: AnimeSvgMotionPathProps) {
  const pathRef = React.useRef<SVGPathElement>(null)
  const [coords, setCoords] = React.useState({ x: 0, y: 0, angle: 0 })

  React.useEffect(() => {
    if (pathRef.current) {
      const p = getPointOnPath(pathRef.current, progress)
      setCoords(p)
    }
  }, [path, progress])

  return (
    <svg
      viewBox={viewBox}
      data-slot="anime-svg-motion-path"
      className={cn("w-full h-full overflow-visible relative", className)}
      {...props}
    >
      {/* Guide track */}
      <path
        ref={pathRef}
        d={path}
        fill="none"
        stroke={pathColor}
        strokeWidth={2}
        strokeDasharray="4 4"
      />

      {/* Motion follower */}
      <g
        transform={`translate(${coords.x}, ${coords.y}) rotate(${coords.angle})`}
        style={{ transition: "transform 0.05s linear" }}
      >
        {children ? (
          children
        ) : (
          <circle r={6} fill="#10b981" className="shadow-[0_0_12px_#10b981]" />
        )}
      </g>
    </svg>
  )
}
